{
 CDefPointer<const CSpecialEffectsDef> pdef;
 long effect=0;
 GetParentThing().PeekBaseDef().GetSubDef(&pdef)&&pdef->GetEffectFromString("AGGRESSIVE",effect);
 if(IS_THING_ALIVE(PEffect)){
