        return -1;
    LHA::CEventPlayOptions options;
    options.Pitch = init.Pitch;
    if (loop)
        options.Is3D = false;
    else
        options.Is3D = Positional;
    options.HeadRelative = attached;
    unsigned long bits = init.GainFaderBits;
    while (bits) {
        int bit = FindFirstSetBit(bits, 16);
        options.SetFlag16(bit, true);
        bits ^= 1 << bit;
